    {
      "id": 1,
      "claim": "The average kinetic energy of particles in any substance is directly proportional to its absolute temperature (KE ∝ T).",
      "evidence": "Kinetic molecular theory: for each translational degree of freedom KE = (1/2)k_B T; solids also have vibrational kinetic energy that contributes (1/2)k_B T per vibrational mode, giving the same temperature dependence.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The temperatures of the four options are approximately: wax at room temperature ≈ 293 K, steam from coffee ≈ 373 K, water in ice‑water mixture ≈ 273 K, ice cube in tea ≤ 273 K (the cube comes from a freezer and is at or below the freezing point until it melts).",
      "evidence": "Standard reference temperatures: 20 °C = 293 K, 0 °C = 273 K, 100 °C = 373 K; ice stored in a freezer is typically well below 0 °C and remains at ≤0 °C while immersed in tea.",
      "weight": 0.35,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Because kinetic energy scales with temperature, the substance with the lowest temperature will have the lowest particle kinetic energy.",
      "evidence": "From step 1, KE ∝ T; therefore a lower T implies a lower KE.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "The ice cube (option D) is at a temperature that is equal to or lower than the water in ice water (option B), and lower than wax or steam, so its particles have the lowest kinetic energy.",
      "evidence": "Step 2 shows D ≤ 273 K while B = 273 K; steps 1 and 3 link lower T to lower KE.",
      "weight": 0.15,
      "depends_on": [2, 3]
    }
  ],
  "answer": "D",
  "confidence": 0.70,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Water in ice water is at 0 °C, whereas the ice cube is at the same temperature or colder (it originates below 0 °C), giving it equal or lower kinetic energy."
    },
    {
      "answer": "A",
      "reason_rejected": "Wax is at room temperature (~20 °C), which is higher than 0 °C, so its particles have higher kinetic energy."
    },
    {
      "answer": "C",
      "reason_rejected": "Steam from coffee is near 100 °C, far hotter than the other options, giving it the highest kinetic energy."
    }
  ]
}
